import 'palette.dart';

/// Buttons, inputs, chips: every control.
const controlRadius = 8.0;

/// Cards, sheets, dialogs. No pills anywhere.
const cardRadius = 12.0;

/// A theme preset: one identity worn by both brightnesses.
///
/// The name is the stored identifier; display names are copy and live in
/// the translations.
enum Preset {
  /// Dark-first: volt on green-black. Unbounded runs much wider than a text face,
  /// so the page title trades size for presence.
  forge(
    light: Palette(
      ground: 0xFFFFFFFF,
      surface: 0xFFFFFFFF,
      fill: 0xFFF2F3E8,
      ink: 0xFF14160D,
      muted: 0xFF5B6055,
      faint: 0xFF969B8C,
      border: 0xFFDEE1D0,
      accent: 0xFFD4F547,
      onAccent: 0xFF121408,
      accentInk: 0xFF55650F,
      destructive: 0xFFB23A28,
    ),
    dark: Palette(
      ground: 0xFF0F100D,
      surface: 0xFF191B15,
      fill: 0xFF232720,
      ink: 0xFFF1F2E9,
      muted: 0xFF9BA092,
      faint: 0xFF6F746A,
      border: 0xFF2A2D24,
      accent: 0xFFD4F547,
      onAccent: 0xFF121408,
      accentInk: 0xFFD4F547,
      destructive: 0xFFFF6B57,
    ),
    textFont: 'Onest',
    titleFont: 'Onest',
    displayFont: 'Unbounded',
    headlineSize: 26,
    headlineWeight: 700,
  ),
  /// Paper and ink with a cobalt accent, light-first the way Forge is dark-first.
  /// Warm neutrals, no green undertone; cobalt rather than vermilion, so the
  /// accent can never be confused with destructive. The house style.
  ink(
    light: Palette(
      ground: 0xFFFFFFFF,
      surface: 0xFFFFFFFF,
      fill: 0xFFF4F1EA,
      ink: 0xFF1A1815,
      muted: 0xFF5D584E,
      faint: 0xFF948F85,
      border: 0xFFE2DED4,
      accent: 0xFF1F4EC8,
      onAccent: 0xFFFFFFFF,
      accentInk: 0xFF1B43A8,
      destructive: 0xFF9E2B25,
    ),
    dark: Palette(
      ground: 0xFF141311,
      surface: 0xFF1E1C19,
      fill: 0xFF2A2721,
      ink: 0xFFF2F0EA,
      muted: 0xFFA29D93,
      faint: 0xFF6F6B63,
      border: 0xFF302D27,
      accent: 0xFF93ADFF,
      onAccent: 0xFF0F1526,
      accentInk: 0xFF93ADFF,
      destructive: 0xFFFF7A66,
    ),
    textFont: 'IBM Plex Sans',
    titleFont: 'Literata',
    displayFont: 'Literata',
    headlineSize: 30,
    headlineWeight: 600,
  ),
  /// The calm tool: cool neutrals where Forge is green-black and Ink is warm
  /// paper, forest green for the accent, nothing raised above its station. One
  /// family carrying everything is the point.
  utility(
    light: Palette(
      ground: 0xFFFFFFFF,
      surface: 0xFFFFFFFF,
      fill: 0xFFF2F4F5,
      ink: 0xFF16181D,
      muted: 0xFF575D66,
      faint: 0xFF949AA4,
      border: 0xFFE1E4E8,
      accent: 0xFF2F7A5F,
      onAccent: 0xFFFFFFFF,
      accentInk: 0xFF27664E,
      destructive: 0xFFC03A2E,
    ),
    dark: Palette(
      ground: 0xFF101214,
      surface: 0xFF1A1D21,
      fill: 0xFF252A2F,
      ink: 0xFFECEEF0,
      muted: 0xFF9AA1AB,
      faint: 0xFF6A7078,
      border: 0xFF2C3138,
      accent: 0xFF64C79B,
      onAccent: 0xFF0E1F18,
      accentInk: 0xFF64C79B,
      destructive: 0xFFFF7365,
    ),
    textFont: 'Golos Text',
    titleFont: 'Golos Text',
    displayFont: 'Golos Text',
    headlineSize: 28,
    headlineWeight: 700,
  ),
  /// Heat: true orange on warm neutrals, amber glow in the dark. The accentInk is
  /// burnt deep enough to read on white, and destructive stays crimson so orange
  /// can never be mistaken for danger.
  ember(
    light: Palette(
      ground: 0xFFFFFFFF,
      surface: 0xFFFFFFFF,
      fill: 0xFFF7F2EA,
      ink: 0xFF191510,
      muted: 0xFF5F584D,
      faint: 0xFF99917F,
      border: 0xFFE8E0D2,
      accent: 0xFFF07514,
      onAccent: 0xFF1F1206,
      accentInk: 0xFF9A4A00,
      destructive: 0xFFB3261E,
    ),
    dark: Palette(
      ground: 0xFF14100C,
      surface: 0xFF1F1913,
      fill: 0xFF2B241C,
      ink: 0xFFF4EFE6,
      muted: 0xFFA69C8C,
      faint: 0xFF746A5C,
      border: 0xFF332B21,
      accent: 0xFFFF9E3D,
      onAccent: 0xFF211204,
      accentInk: 0xFFFF9E3D,
      destructive: 0xFFFF7361,
    ),
    textFont: 'Rubik',
    titleFont: 'Rubik',
    displayFont: 'Rubik',
    headlineSize: 28,
    headlineWeight: 700,
  );

  final Palette light;
  final Palette dark;

  /// Everything that reads: body, labels, controls.
  final String textFont;

  /// Page and dialog titles, where a preset may hand headlines to a second
  /// face without shouting everywhere [displayFont] does.
  final String titleFont;

  /// Headlines and numbers worth a shout, nothing else.
  final String displayFont;

  /// The page title, tuned per display face: different faces fill the same
  /// box very differently at one size. The weight is CSS-style, 100 to 900.
  final double headlineSize;
  final int headlineWeight;

  new({
    required this.light,
    required this.dark,
    required this.textFont,
    required this.titleFont,
    required this.displayFont,
    required this.headlineSize,
    required this.headlineWeight,
  });

  /// The house style: a first launch, and a stored name this build does not
  /// know.
  static const fallback = Preset.ink;
}

